<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $patient->full_name }}</title><style>body{max-width:1100px;margin:40px auto;background:#fcfafb;color:#332d35;font:14px Arial}a{color:#bd3168;text-decoration:none}h1{font-size:30px;margin:8px 0}.hero,.quick{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.status{margin-left:auto;padding:7px;background:#e4f7f0;color:#15775a;border-radius:20px;font-weight:bold}.quick{margin:20px 0}.quick a,button{padding:10px;border-radius:8px;border:1px solid #eadde2;background:white;color:#a63062;font-weight:bold}.quick .primary,button{background:#dc4f87;color:white;border-color:#dc4f87}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:white;border:1px solid #f0e6ea;border-radius:12px;padding:18px}.full{grid-column:1/-1}.muted,small{color:#817780}.pill{display:inline-block;margin:4px;padding:6px 8px;background:#fff1f6;color:#a63062;border-radius:12px}.money{display:grid;grid-template-columns:1fr auto;gap:10px}.due{color:#c53d57}textarea,input,select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #e7dce0;border-radius:7px;margin:5px 0;font:inherit}textarea{min-height:68px}.clinical{display:grid;grid-template-columns:1fr 1fr;gap:12px}.notice{background:#e4f7f0;padding:10px;color:#15775a}.note{padding:10px 0;border-top:1px solid #f5edef}@media(max-width:650px){body{margin:20px}.grid,.clinical{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><a href="{{ route('pacientes.index') }}">← Pacientes</a>@if(session('status'))<p class="notice">{{ session('status') }}</p>@endif<header class="hero"><div><h1>{{ $patient->full_name }}</h1><span class="muted">{{ $patient->document_type }} {{ $patient->document_number }} · {{ $patient->phone }}</span></div><span class="status">● PACIENTE {{ mb_strtoupper($patient->status) }}</span></header><div class="quick"><a class="primary" href="{{ route('agenda.create', ['patient_id'=>$patient->id]) }}">＋ Nueva cita</a><a href="#historia">📷 Historia clínica</a><a href="#pagos">💰 Registrar pago</a><a href="#notas">📝 Nueva nota</a></div><main class="grid"><article class="card"><h2>📅 Próxima cita</h2>@if($nextAppointment)<b>{{ $nextAppointment->treatment->name }}</b><p>{{ $nextAppointment->starts_at->translatedFormat('d M Y · h:i A') }}</p>@else<p class="muted">No hay citas próximas.</p>@endif</article><article class="card"><h2>✨ Tratamientos realizados</h2>@forelse($completed as $appointment)<span class="pill">{{ $appointment->treatment->name }}</span>@empty<p class="muted">Sin tratamientos realizados.</p>@endforelse</article><article id="pagos" class="card"><h2>💰 Estado de cuenta</h2><div class="money"><span>Total tratamientos</span><b>${{ number_format($total,0,',','.') }}</b><span>Pagado</span><b>${{ number_format($paid,0,',','.') }}</b><span class="due">Pendiente</span><b class="due">${{ number_format(max(0,$total-$paid),0,',','.') }}</b></div><form method="POST" action="{{ route('patients.payments.store',$patient) }}">@csrf<input name="amount" type="number" min="1" placeholder="Valor del pago"><select name="method"><option value="efectivo">Efectivo</option><option value="transferencia">Transferencia</option><option value="tarjeta">Tarjeta</option></select><button>Registrar pago</button></form></article><article id="notas" class="card"><h2>📝 Últimas notas</h2><form method="POST" action="{{ route('patients.notes.store',$patient) }}">@csrf<textarea name="body" placeholder="Añade una nota de seguimiento…"></textarea><button>Guardar nota</button></form>@forelse($patient->notes->take(3) as $note)<div class="note">{{ $note->body }}<small>{{ $note->author?->name ?? 'Equipo clínico' }} · {{ $note->created_at->format('d/m/Y') }}</small></div>@empty<p class="muted">Sin notas.</p>@endforelse</article><article id="historia" class="card full"><h2>🩺 Historia clínica</h2><form method="POST" action="{{ route('patients.clinical.update',$patient) }}">@csrf @method('PATCH')<div class="clinical"><label>Antecedentes<textarea name="medical_history">{{ $patient->medical_history }}</textarea></label><label>Alergias<textarea name="allergies">{{ $patient->allergies }}</textarea></label><label>Medicamentos<textarea name="medications">{{ $patient->medications }}</textarea></label><label>Contraindicaciones<textarea name="contraindications">{{ $patient->contraindications }}</textarea></label><label>Observaciones<textarea name="clinical_observations">{{ $patient->clinical_observations }}</textarea></label></div><button>Guardar historia clínica</button></form></article><article class="card full"><h2>Historial de citas</h2>@forelse($patient->appointments as $appointment)<p><b>{{ $appointment->treatment->name }}</b> · {{ $appointment->starts_at->format('d/m/Y H:i') }} <small>({{ str_replace('_',' ',$appointment->status) }})</small></p>@empty<p class="muted">No hay citas.</p>@endforelse</article></main></body></html>
